package com.richfield.smartpantry;
import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import java.util.*;
public class RecipeAdapter extends RecyclerView.Adapter<RecipeAdapter.H>{public interface Click{void click(Recipe r);}private final ArrayList<Recipe>d;private final Click c;public RecipeAdapter(ArrayList<Recipe>d,Click c){this.d=d;this.c=c;}public H onCreateViewHolder(ViewGroup p,int v){TextView t=new TextView(p.getContext());t.setPadding(36,32,36,32);t.setTextSize(18);return new H(t);}public void onBindViewHolder(H h,int p){Recipe r=d.get(p);h.t.setText("🍲  "+r.name);h.t.setOnClickListener(v->c.click(r));}public int getItemCount(){return d.size();}static class H extends RecyclerView.ViewHolder{TextView t;H(View v){super(v);t=(TextView)v;}}}
